use renderer::engine::{Draw, Engine, IDENTITY, Material, MeshData, Vertex, View};
use renderer::graph::{BufferDesc, Graph};
use std::alloc::{GlobalAlloc, Layout, System};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};

struct Counter;
static COUNTING: AtomicBool = AtomicBool::new(false);
static ALLOCS: AtomicUsize = AtomicUsize::new(0);
static BYTES: AtomicUsize = AtomicUsize::new(0);
#[global_allocator]
static ALLOCATOR: Counter = Counter;
unsafe impl GlobalAlloc for Counter {
    unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
        if COUNTING.load(Ordering::Relaxed) {
            ALLOCS.fetch_add(1, Ordering::Relaxed);
            BYTES.fetch_add(layout.size(), Ordering::Relaxed);
        }
        unsafe { System.alloc(layout) }
    }
    unsafe fn dealloc(&self, pointer: *mut u8, layout: Layout) {
        unsafe { System.dealloc(pointer, layout) }
    }
    unsafe fn realloc(&self, pointer: *mut u8, layout: Layout, size: usize) -> *mut u8 {
        if COUNTING.load(Ordering::Relaxed) {
            ALLOCS.fetch_add(1, Ordering::Relaxed);
            BYTES.fetch_add(size, Ordering::Relaxed);
        }
        unsafe { System.realloc(pointer, layout, size) }
    }
}
fn measure<T>(f: impl FnOnce() -> T) -> (T, usize, usize) {
    ALLOCS.store(0, Ordering::Relaxed);
    BYTES.store(0, Ordering::Relaxed);
    COUNTING.store(true, Ordering::Relaxed);
    let result = std::hint::black_box(f());
    COUNTING.store(false, Ordering::Relaxed);
    (result, ALLOCS.load(Ordering::Relaxed), BYTES.load(Ordering::Relaxed))
}
fn main() {
    let mut graph = Graph::new();
    for index in 0..2048 {
        let buffer = graph.buffer(format!("resource {index}"), BufferDesc { size: 4 }).unwrap();
        graph.upload_buffer(format!("upload {index}"), buffer, 0, vec![0; 4]).unwrap();
        graph.readback_buffer(format!("readback {index}"), buffer, 0, 4).unwrap();
    }
    let (plan, calls, bytes) = measure(|| graph.compile().unwrap());
    assert_eq!(plan.pass_count(),4096);
    println!("compile resources=2048 passes=4096 allocations={calls} allocated_bytes={bytes}");
    let mut engine = Engine::new(1,1).unwrap();
    let mesh = engine.create_mesh(MeshData::new(&[
        Vertex { position:[-1.0,-1.0,0.5], color:[1.0;4] },
        Vertex { position:[1.0,-1.0,0.5], color:[1.0;4] },
        Vertex { position:[0.0,1.0,0.5], color:[1.0;4] },
    ], &[0,1,2]).unwrap()).unwrap();
    let material=engine.create_material(Material::default()).unwrap();
    let view=View{ width:32,height:32,clip_from_world:IDENTITY,clear_color:[0.0;4] };
    let draws=vec![Draw{mesh,material,world_from_model:IDENTITY};8192];
    let snapshot=engine.snapshot(&view,&draws).unwrap();
    let (frame,calls,bytes)=measure(||snapshot.build_graph(false,|_,color| Ok(color)).unwrap());
    assert_eq!(frame.graph.compile().unwrap().pass_count(),3);
    println!("frame_build draws=8192 allocations={calls} allocated_bytes={bytes}");
}

scaling_probe.harness_source_utf8:
use renderer::graph::{
    Access, AccessKind, AccessPurpose, AccessRange, BufferDesc, GraphCapacity, GraphPool,
    PassKind,
};
use std::{hint::black_box, time::Instant};

const WARMUP: usize = 8;

#[cfg(windows)]
fn pin_measurement_process() {
    use std::ffi::c_void;
    unsafe extern "system" {
        fn GetCurrentProcess() -> *mut c_void;
        fn GetProcessAffinityMask(process: *mut c_void, process_mask: *mut usize, system_mask: *mut usize) -> i32;
        fn SetProcessAffinityMask(process: *mut c_void, mask: usize) -> i32;
    }
    let mut allowed = 0usize;
    let mut system = 0usize;
    // Only this probe process is pinned, identically for before and after.
    unsafe {
        let process = GetCurrentProcess();
        assert_ne!(GetProcessAffinityMask(process, &mut allowed, &mut system), 0);
        assert_ne!(allowed, 0);
        let selected = allowed & allowed.wrapping_neg();
        assert_ne!(SetProcessAffinityMask(process, selected), 0);
        eprintln!("measurement_process_affinity_mask={selected:#x}");
    }
}

fn capacity(n: usize) -> GraphCapacity {
    GraphCapacity {
        resources: 1,
        passes: n,
        accesses: n,
        draws: 0,
        dependencies: n,
        initial_ranges: 0,
        name_bytes: n + 1,
        upload_bytes: 0,
        edges: n,
        segments: 2 * n + 1,
        readers: n,
    }
}

fn report(scenario: &str, n: usize, raw: &[u128]) {
    let mut sorted = raw.to_vec();
    sorted.sort_unstable();
    println!(
        r#"{{"scenario":"{scenario}","passes":{n},"median_ns":{},"raw_ns":{raw:?}}}"#,
        sorted[sorted.len() / 2]
    );
}

fn intervals(n: usize, order: &str, wide_read: bool) {
    let mut offsets: Vec<_> = (0..n).collect();
    if order == "descending" {
        offsets.reverse();
    } else if order == "shuffled" {
        let mut seed = 0x6a09_e667_f3bc_c909_u64;
        for index in (1..n).rev() {
            seed ^= seed << 13;
            seed ^= seed >> 7;
            seed ^= seed << 17;
            offsets.swap(index, (seed % (index as u64 + 1)) as usize);
        }
    }
    let mut pool = GraphPool::new(capacity(n + 1), 1).unwrap();
    let mut raw = Vec::with_capacity(9);
    for sample in 0..WARMUP + 9 {
        let mut graph = pool.begin().unwrap();
        let stride = if wide_read { 4 } else { 8 };
        let buffer = graph.buffer("b", BufferDesc { size: n as u64 * stride }).unwrap();
        for &offset in &offsets {
            let start = offset as u64 * stride;
            graph.declare_pass("p", PassKind::Copy, &[Access {
                resource: buffer.into(),
                range: AccessRange::Buffer(start..start + 4),
                kind: AccessKind::Write,
                purpose: AccessPurpose::CopyDestination,
            }], true).unwrap();
        }
        if wide_read {
            graph.declare_pass("r", PassKind::Copy, &[Access {
                resource: buffer.into(),
                range: AccessRange::Buffer(0..n as u64 * stride),
                kind: AccessKind::Read,
                purpose: AccessPurpose::CopySource,
            }], true).unwrap();
        }
        let started = Instant::now();
        let plan = graph.compile().unwrap();
        let elapsed = started.elapsed().as_nanos();
        assert_eq!(plan.pass_count(), n + usize::from(wide_read));
        black_box(&plan);
        if sample >= WARMUP { raw.push(elapsed); }
    }
    let scenario = if wide_read { "fragmented_wide_read_compile" } else { "fragmented_compile" };
    report(&format!("{scenario}_{order}"), n, &raw);
}

fn dependencies(n: usize) {
    let mut pool = GraphPool::new(capacity(n), 1).unwrap();
    let mut handles = Vec::with_capacity(n);
    let mut raw = Vec::with_capacity(9);
    for sample in 0..WARMUP + 9 {
        let mut graph = pool.begin().unwrap();
        handles.clear();
        for _ in 0..n {
            handles.push(graph.declare_pass("p", PassKind::Copy, &[], true).unwrap());
        }
        let started = Instant::now();
        for p in 1..n {
            graph.depends_on(handles[p], handles[p - 1]).unwrap();
        }
        let elapsed = started.elapsed().as_nanos();
        black_box(&graph);
        if sample >= WARMUP { raw.push(elapsed); }
    }
    report("explicit_dependency_insertion", n, &raw);
}

fn main() {
    #[cfg(windows)]
    pin_measurement_process();
    for n in [1024, 2048, 4096, 8192] {
        for order in ["ascending", "descending", "shuffled"] { intervals(n, order, false); }
        for order in ["ascending", "shuffled"] { intervals(n, order, true); }
    }
    for n in [1024, 2048, 4096, 8192, 16384] { dependencies(n); }
}
